      <el-alert v-if="loadError" title="作品暂时加载失败，请稍后重试" type="warning" :closable="false" show-icon><el-button text @click="load">重新加载</el-button></el-alert>
      <div class="portfolio-grid"><button v-for="(item,index) in works" :key="item.id" class="portfolio-card" @click="detail('sheyingzuopin',item.id)"><div class="portfolio-image"><img :src="imageUrl(item.zuopintupian)" :alt="item.zuopinmingcheng" loading="lazy" /><span>{{ String(index+1).padStart(2,'0') }}</span></div><div class="portfolio-caption"><h3>{{ item.zuopinmingcheng }}</h3><span>{{ item.sheyingxingming || '花海摄影' }} <span aria-hidden="true">↗</span></span></div></button></div>
      <el-empty v-if="!loading && !loadError && !works.length" description="作品正在准备中，敬请期待" />
    </section>
    <section class="studio-photographers studio-section"><header class="section-heading"><div><span class="eyebrow">MEET THE PHOTOGRAPHERS</span><h2>找到懂你的摄影师</h2><p>了解作品与擅长风格，再选择适合自己的拍摄伙伴。</p></div><el-button text @click="go('sheyingshixinxiList')">查看全部 ↗</el-button></header><div class="photographer-grid"><button v-for="person in photographers" :key="person.id" class="photographer-card" @click="detail('sheyingshixinxi',person.id)"><img :src="imageUrl(person.sheyingshizhaopian)" :alt="person.sheyingxingming" loading="lazy" /><div><span class="photographer-category">{{ person.fenlei || '摄影师' }}</span><h3>{{ person.sheyingxingming }}</h3><p>{{ plainText(person.jianjie) || '用心观察，以影像表达。' }}</p><div class="photographer-bottom"><span>{{ person.yuyuejiage != null ? '¥ ' + person.yuyuejiage : '价格详询' }}</span><span>查看档期 ↗</span></div></div></button></div><el-empty v-if="!loading && !photographers.length" description="更多摄影师信息请咨询工作室" /></section>
