<script setup>
import { ref, getCurrentInstance } from 'vue'
import { useRouter } from 'vue-router'
const context = getCurrentInstance().appContext.config.globalProperties
const router = useRouter()
const heroImage = process.env.BASE_URL + 'brand/huahai-hero.jpg'
const works = ref([]), photographers = ref([]), links = ref([]), loading = ref(true), loadError = ref(false)
const imageUrl = value => { const first = (value || '').split(',')[0]; return /^https?:\/\//i.test(first) ? first : first ? context.$config.url + first : '' }
const plainText = value => { const element = document.createElement('div'); element.innerHTML = value || ''; return element.textContent || '' }
const safeLink = value => /^https?:\/\//i.test(value || '') ? value : undefined
const go = page => router.push('/index/' + page)
const detail = (table,id) => router.push({ path: '/index/' + table + 'Detail', query: { id } })
const steps = [{ number: '01', title: '发现喜欢的风格', text: '浏览真实作品，了解摄影师的拍摄风格与服务价格。' }, { number: '02', title: '选择专属的时间', text: '选择摄影师与可用档期，提交联系方式和预约信息。' }, { number: '03', title: '确认拍摄安排', text: '等待预约审核，通过在线咨询沟通拍摄想法与细节。' }, { number: '04', title: '赴一场光影之约', text: '按约定时间到场，让镜头记录自然而独特的你。' }]
async function load() {
 loading.value = true; loadError.value = false
 const results = await Promise.allSettled([context.$http.get('sheyingzuopin/list',{params:{page:1,limit:6,sort:'id',order:'desc'}}),context.$http.get('sheyingshixinxi/list',{params:{page:1,limit:3,sfsh:'是'}}),context.$http.get('friendshiplink/list',{params:{page:1,limit:8}})])
 if(results[0].status === 'fulfilled') works.value = results[0].value.data.data.list; else loadError.value = true
 if(results[1].status === 'fulfilled') photographers.value = results[1].value.data.data.list
 if(results[2].status === 'fulfilled') links.value = results[2].value.data.data.list
 loading.value = false
}
load()
</script>
